mapper.select:
SELECT
FROM fm_process_instance WHERE 1 = 1
ORDER BY ${orderBy} ${sortType}

mapper.update:
UPDATE fm_process_instance
SET INSTANCE_STATUS = #{targetStatus,jdbcType=VARCHAR},
    END_DATE = #{endDate,jdbcType=TIMESTAMP},
    UUSERID = #{uuserid,jdbcType=VARCHAR},
    UDATE = #{udate,jdbcType=TIMESTAMP}
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND PROCESS_INSTANCE_ID = #{processInstanceId,jdbcType=VARCHAR}
  AND INSTANCE_STATUS = #{currentStatus,jdbcType=VARCHAR}
